with cleaned as (select id, order_id, carrier, shipped_date, status, date_add(delivered_date, 47) as delivered_date_plus_47d, coalesce(carrier, 'DIRECT') as carrier_filled from shipments where shipped_date > to_date('2023-06-28') and shipped_date >= '2025-09-01') select status, sort_array(collect_set(status)) as status_list, count_if(status = 'RETURNED') as returned_events, sort_array(collect_set(carrier)) as carrier_list, count(*) filter (where status = 'DELIVERED') as delivered_rows, count(*) as cnt, count(distinct order_id) as distinct_order_ids from cleaned group by status having count(*) >= 1;
